      box-shadow: 0 0 0 6px rgba(255,93,93,.12);
    }

    h1{
      font-size: clamp(2.8rem, 6vw, 5.2rem);
      line-height: .95;
      margin:0 0 16px;
      letter-spacing:-.04em;
      text-transform:uppercase;
    }

    h1 .accent{ color: var(--accent); }
    h1 .cyan{ color: var(--accent2); }

    .hero p{
      color:var(--muted);
      max-width: 62ch;
      font-size:1.05rem;
      line-height:1.7;
      margin:0 0 24px;
    }

    .hero-actions{
      display:flex;
      gap:14px;
      flex-wrap:wrap;
      margin-bottom:26px;
    }

    .stats{
      display:grid;
      grid-template-columns: repeat(3, 1fr);
      gap:14px;
      margin-top:22px;
    }

    .stat{
      background: rgba(19,27,39,.72);
      border:1px solid rgba(255,255,255,.08);
      border-radius: var(--radius);
      padding:18px;
      box-shadow: var(--shadow);
    }

    .stat strong{
      display:block;
      font-size:1.6rem;
      margin-bottom:6px;
    }
    .stat span{ color:var(--muted); font-size:.95rem; }

    .hero-card{
      background:
        linear-gradient(180deg, rgba(19,27,39,.92), rgba(15,21,32,.88));
      border:1px solid rgba(255,255,255,.08);
      border-radius: 28px;
      padding:22px;
      box-shadow: var(--shadow);
      position:relative;
      overflow:hidden;
    }

    .hero-card::after{
      content:"";
      position:absolute;
      inset:auto -40px -40px auto;
      width:180px;
      height:180px;
      background: radial-gradient(circle, rgba(255,176,0,.22), transparent 65%);
      pointer-events:none;
    }

    .card-top{
      display:flex;
      justify-content:space-between;
      align-items:center;
      margin-bottom:16px;
      gap:12px;
    }

    .live{
      display:inline-flex;
      align-items:center;
      gap:10px;
      color:var(--muted);
      font-size:.9rem;
      font-weight:600;
    }
    .pulse{
      width:10px; height:10px; border-radius:50%;
      background:var(--danger);
      box-shadow:0 0 0 8px rgba(255,93,93,.12);
      animation:pulse 1.4s infinite;
    }

    @keyframes pulse{
      0%{ transform:scale(.9); box-shadow:0 0 0 0 rgba(255,93,93,.2);}
      70%{ transform:scale(1); box-shadow:0 0 0 10px rgba(255,93,93,0);}
      100%{ transform:scale(.9); box-shadow:0 0 0 0 rgba(255,93,93,0);}
    }

    .map-preview{
      border-radius:22px;
      min-height:280px;
      background:
        linear-gradient(rgba(0,0,0,.25), rgba(0,0,0,.55)),
        url("https://images.unsplash.com/photo-1511512578047-dfb367046420?auto=format&fit=crop&w=1200&q=80") center/cover;
      border:1px solid rgba(255,255,255,.08);
      position:relative;
      overflow:hidden;
    }

    .map-overlay{
      position:absolute;
      inset:auto 0 0 0;
      padding:18px;
      background: linear-gradient(180deg, transparent, rgba(0,0,0,.78));
    }

    .map-overlay h3{
      margin:0 0 6px;
      font-size:1.4rem;
    }

    .map-overlay p{
      margin:0;
      color:#cdd7e3;
      font-size:.95rem;
    }

    /* Sections */
    section{
      padding:70px 0;
    }

    .section-title{
      display:flex;
      justify-content:space-between;
      align-items:end;
      gap:18px;
      margin-bottom:24px;
      flex-wrap:wrap;
    }

    .section-title h2{
      margin:0;
      font-size: clamp(1.7rem, 3vw, 2.6rem);
      text-transform:uppercase;
      letter-spacing:-.03em;
    }

    .section-title p{
      margin:0;
      color:var(--muted);
      max-width:60ch;
      line-height:1.6;
    }

    .grid{
      display:grid;
      gap:18px;
    }

    .cards-3{ grid-template-columns: repeat(3, 1fr); }
    .cards-2{ grid-template-columns: repeat(2, 1fr); }

    .card{
      background: rgba(19,27,39,.82);
      border:1px solid rgba(255,255,255,.08);
      border-radius: var(--radius);
      padding:22px;
      box-shadow: var(--shadow);
    }

    .card h3{ margin:0 0 10px; font-size:1.15rem; }
    .card p{ margin:0; color:var(--muted); line-height:1.65; }

    .icon{
      width:48px;
      height:48px;
      border-radius:14px;
      display:grid;
      place-items:center;
      margin-bottom:14px;
      background: linear-gradient(135deg, rgba(255,176,0,.18), rgba(45,212,191,.14));
      border:1px solid rgba(255,255,255,.08);
      font-size:1.2rem;
    }

    /* Tournament section */
    .tournament{
      background: linear-gradient(180deg, rgba(255,255,255,.02), rgba(255,255,255,0));
    }

    .tourney-banner{
      display:grid;
      grid-template-columns: 1fr 1fr;
      gap:18px;
      align-items:center;
    }

    .match{
      display:flex;
      justify-content:space-between;
      align-items:center;
      gap:12px;
      padding:16px;
      border-radius:18px;
      background: rgba(255,255,255,.04);
      border:1px solid rgba(255,255,255,.07);
      margin-top:12px;
    }

    .team{
      display:flex;
      align-items:center;
      gap:12px;
      font-weight:700;
    }

    .badge{
      padding:6px 10px;
      border-radius:999px;
      font-size:.8rem;
      background: rgba(45,212,191,.12);
      color: var(--accent2);
      border:1px solid rgba(45,212,191,.18);
    }

    /* Footer */
    footer{
      border-top:1px solid rgba(255,255,255,.08);
      padding:30px 0;
      color:var(--muted);
      background: rgba(0,0,0,.15);
    }

    .footer-row{
      display:flex;
      justify-content:space-between;
      gap:14px;
      flex-wrap:wrap;
      align-items:center;
    }

    /* Responsive */
    @media (max-width: 900px){
      .hero-grid, .tourney-banner, .cards-3, .cards-2{
        grid-template-columns: 1fr;
      }
      .stats{
        grid-template-columns:1fr;
      }
      .nav{
        flex-direction:column;
        align-items:flex-start;
      }
    }

    @media (max-width: 600px){
      .hero{
        padding:60px 0 50px;
      }
      .nav-links{
        gap:14px;
      }
      .hero-actions .btn{
        width:100%;
      }
    }
  </style>
</head>
